Next, implement a CreateWorldTransform function, as follows:
void Actor::ComputeWorldTransform()
{
if (mRecomputeWorldTransform)
{
mRecomputeWorldTransform = false;
// Scale, then rotate, then translate
mWorldTransform = Matrix4::CreateScale(mScale);
mWorldTransform *= Matrix4::CreateRotationZ(mRotation);
mWorldTransform *= Matrix4::CreateTranslation(
Vector3(mPosition.x, mPosition.y, 0.0f));
}
Note that you use various Matrix4 static functions to create the component matrices.
CreateScale creates a uniform scale matrix, CreateRotationZ creates a rotation matrix
about the z-axis, and CreateTranslation creates a translation matrix.
You call ComputeWorldTransform in Actor::Update, both before you update any
components and after you call UpdateActor (in case it changes in the interim):
void Actor::Update(float deltaTime)
{
if (mState == EActive)
{
ComputeWorldTransform();
UpdateComponents(deltaTime);
UpdateActor(deltaTime);
ComputeWorldTransform();
}
}
